body.script:
const buildUrl = "https://cdn.jsdelivr.net/gh/organization-schoogls/y@main/Build";
const loaderUrl = buildUrl + "/build.loader.js";
const config = {
    dataUrl: buildUrl + "/build.data.unityweb",
    frameworkUrl: buildUrl + "/build.framework.js.unityweb",
    codeUrl: buildUrl + "/build.wasm.unityweb",
    streamingAssetsUrl: "StreamingAssets",
    companyName: "AutismDev",
    productName: "Gravity Mod",
    productVersion: "1.0.0"
};

const canvas = document.querySelector("#unity-canvas");
const loadingCover = document.querySelector("#loading-cover");

document.addEventListener('contextmenu', e => e.preventDefault());

//================== REMOVE ADS ==================//
function FullAdShow(){return;}         // FULL SCREEN ADS REMOVED
function RewardedShow(){return;}       // REWARD ADS REMOVED
function StickyAdActivity(){return;}   // BANNER ADS REMOVED
function Review(){return;}
function PromptShow(){return;}
function GetPayments(){return "none";}
function InitLeaderboards(){}
function GetLeaderboardScores(){}
function SetLeaderboardScores(){}
function ConsumePurchase(){}
function ConsumePurchases(){}
//===============================================//

// LOAD UNITY ENGINE
const script=document.createElement("script");
script.src=loaderUrl;
script.onload=()=>{
    createUnityInstance(canvas,config,()=>{}).then(()=>{
        loadingCover.style.display="none";
    });
};
document.body.appendChild(script);
